const restoreCustomer = `-- name: RestoreCustomer :execrows
UPDATE customers SET deleted_at = NULL
WHERE organization_id = $1 AND uuid = $2 AND deleted_at IS NOT NULL
`

type RestoreCustomerParams struct {
	OrganizationID int64     `json:"organization_id"`
	Uuid           uuid.UUID `json:"uuid"`
}

// Bulk delete rollback.
func (q *Queries) RestoreCustomer(ctx context.Context, arg RestoreCustomerParams) (int64, error) {
	result, err := q.db.Exec(ctx, restoreCustomer, arg.OrganizationID, arg.Uuid)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

