const upsertCustomerIdentity = `-- name: UpsertCustomerIdentity :one
INSERT INTO customer_identities (phone_e164, phone_verified_at)
VALUES ($1, $2)
ON CONFLICT (phone_e164) DO UPDATE SET phone_verified_at = GREATEST(customer_identities.phone_verified_at, EXCLUDED.phone_verified_at)
RETURNING id, uuid, phone_e164, phone_verified_at, created_at, updated_at
`

type UpsertCustomerIdentityParams struct {
	PhoneE164  string             `json:"phone_e164"`
	VerifiedAt pgtype.Timestamptz `json:"verified_at"`
}

// Platform-level: called only after the phone was proven.
func (q *Queries) UpsertCustomerIdentity(ctx context.Context, arg UpsertCustomerIdentityParams) (CustomerIdentity, error) {
	row := q.db.QueryRow(ctx, upsertCustomerIdentity, arg.PhoneE164, arg.VerifiedAt)
	var i CustomerIdentity
	err := row.Scan(
		&i.ID,
		&i.Uuid,
		&i.PhoneE164,
		&i.PhoneVerifiedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
